    {
      "category": "wrong_component_type",
      "components": ["C3"],
      "pins": ["C3.1", "C3.2"],
      "nets": ["PWM", "/PWM_OUT"],
      "observed": "C3 is a 100nF capacitor connected in series between the MCU PWM net (PWM) and the fan PWM output net (/PWM_OUT).",
      "expected": "The fan PWM input should be DC-coupled to the MCU PWM output, either directly or through a series resistor, not a capacitor.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "C3 | 100nF | Capacitor_SMD:C_0805_2012Metric | Device:C_Small"
        },
        {
          "source": "netlist",
          "quote": "/PWM_OUT : C3.1(passive) J2.4(Pin_4,passive)"
        },
        {
          "source": "netlist",
          "quote": "PWM : C3.2(passive) J4.1(MISO,passive) R2.1(passive) U2.6(PB1,bidirectional) U3.6(PB1,bidirectional)"
        }
      ],
      "impact": "The series capacitor blocks DC and differentiates the PWM signal, so the fan's PWM input will not receive a valid duty-cycle signal; the fan may not respond or may run at full speed.",
      "confidence": 0.95
    }
  ],
  "summary": "The design contains a series capacitor (C3) in the fan PWM signal path, which will prevent the fan from receiving a proper DC PWM signal. No other anomalies were found."
}

